package com.mfg.wms.entity;
import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;import java.time.*;
@Entity @Table(name="wms_stock_txn",catalog="src_wms") @Getter @Setter @NoArgsConstructor public class StockTransaction{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="txn_no")private String txnNo;@Column(name="material_code")private String materialCode;@Column(name="warehouse_code")private String warehouseCode;@Column(name="location_code")private String locationCode;@Column(name="batch_no")private String batchNo;@Column(name="txn_type")private String txnType;@Column(name="txn_direction")private String direction;@Column(name="txn_qty")private BigDecimal txnQty;@Column(name="unit_code")private String unitCode;@Column(name="unit_cost")private BigDecimal unitCost;@Column(name="source_no")private String sourceNo;@Column(name="prod_order_no")private String prodOrderNo;@Column(name="work_order_no")private String workOrderNo;@Column(name="txn_date")private LocalDate txnDate;@Column(name="operator_code")private String operatorCode;}
